// Implement secrets rotation monitoring
async function checkSecretRotation() {
  const secrets = [
    { name: 'database', lastRotated: process.env.DB_SECRET_ROTATED_AT },
    { name: 'api-keys', lastRotated: process.env.API_SECRET_ROTATED_AT }
  ];

  const maxAgeDays = 90;

  for (const secret of secrets) {
    if (secret.lastRotated) {
      const rotatedDate = new Date(secret.lastRotated);
      const daysSinceRotation = (Date.now() - rotatedDate) / (1000 * 60 * 60 * 24);

      if (daysSinceRotation > maxAgeDays) {
        console.warn(`⚠️  ${secret.name} secret hasn't been rotated in ${Math.floor(daysSinceRotation)} days`);
        // Trigger rotation notification
      }
