### **Production-Ready Secrets Management Options**

#### **Option 1: AWS Secrets Manager (for AWS deployments)**
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

const getSecret = async (secretName) => {
  const client = new SecretsManagerClient({
    region: process.env.AWS_REGION || 'us-east-1'
  });

  try {
    const data = await client.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );
    return JSON.parse(data.SecretString);
  } catch (error) {
    console.error('Failed to retrieve secret:', error);
    process.exit(1);
  }
};

// Usage
const secrets = await getSecret('myapp/secrets');
process.env.JWT_SECRET = secrets.jwtSecret;
process.env.DATABASE_URL = secrets.databaseUrl;
```

#### **Option 2: Azure Key Vault (for Azure deployments)**
```javascript
const { SecretClient } = require("@azure/keyvault-secrets");
const { DefaultAzureCredential } = require("@azure/identity");

const keyVaultName = process.env.KEY_VAULT_NAME;
const KVUri = `https://${keyVaultName}.vault.azure.net`;
const credential = new DefaultAzureCredential();
const client = new SecretClient(KVUri, credential);

const getSecret = async (secretName) => {
  const secret = await client.getSecret(secretName);
  return secret.value;
};

// Usage
process.env.JWT_SECRET = await getSecret('jwt-secret');
process.env.DATABASE_URL = await getSecret('database-url');
```

#### **Option 3: HashiCorp Vault (cloud-agnostic)**
```javascript
const vault = require('node-vault')({
  endpoint: process.env.VAULT_ADDR,
  token: process.env.VAULT_TOKEN
});

const getSecret = async (path) => {
  const data = await vault.read(path);
  return data.data;
};

// Usage
const secrets = await getSecret('secret/myapp');
process.env.JWT_SECRET = secrets.jwtSecret;
process.env.DATABASE_URL = secrets.databaseUrl;
```

