const crypto = require('crypto');
const fs = require('fs');

function verifyCredentialIntegrity(filePath) {
  const signaturePath = filePath + '.sha256';

  if (!fs.existsSync(signaturePath)) {
    throw new Error(`Credential signature not found: ${signaturePath}`);
  }

  const content = fs.readFileSync(filePath);
  const expectedSignature = fs.readFileSync(signaturePath, 'utf8');
  const actualSignature = crypto.createHash('sha256').update(content).digest('hex');

  if (!crypto.timingSafeEqual(Buffer.from(actualSignature), Buffer.from(expectedSignature))) {
    throw new Error('Credential file integrity verification failed');
  }

  return true;
}
