## ✅ Recommended Improvements

### 1. **Separate secrets loading from application code**

Create a dedicated secrets module:

```javascript
// config/secrets.js
const { createHash } = require('crypto');

class SecretsManager {
  constructor() {
    this.secrets = new Map();
    this.canaryPrefixes = ['CANARY', 'test-', 'dummy-', 'placeholder-'];
  }

  async loadFromEnv() {
    const envPath = process.env.DOTENV_PATH || '.env';
    try {
      const fs = require('fs');
      if (fs.existsSync(envPath)) {
        const content = fs.readFileSync(envPath, 'utf8');
        const lines = content.split('\n');

        for (const line of lines) {
          const trimmed = line.trim();
          if (trimmed && !trimmed.startsWith('#')) {
            const [key, ...valueParts] = trimmed.split('=');
            const value = valueParts.join('=').trim();

            if (this.isCanaryValue(value)) {
              console.warn(`[WARNING] Canary/placeholder value detected for ${key}`);
            }

            this.secrets.set(key, value);
          }
        }
      }
    } catch (error) {
      console.warn('[INFO] No .env file found, using system environment');
    }

    // Merge with process.env
    this.secrets.set('process.env', process.env);
  }

  isCanaryValue(value) {
    const lowerValue = (value + '').toLowerCase();
    return this.canaryPrefixes.some(prefix => lowerValue.startsWith(prefix));
  }

  get(key) {
    return this.secrets.get(key) || process.env[key];
  }

  async loadFromSecretsManager(service = 'aws-secrets-manager') {
    // Future implementation: Load from AWS Secrets Manager, HashiCorp Vault, etc.
    if (service === 'aws-secrets-manager') {
      const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
      const client = new SecretsManagerClient({});

      const secretName = process.env.SECRET_NAME || 'app/secrets';
      const command = new GetSecretValueCommand({ SecretId: secretName });
      const response = await client.send(command);

      if (response.SecretString) {
        const secrets = JSON.parse(response.SecretString);
        Object.entries(secrets).forEach(([key, value]) => this.secrets.set(key, value));
      }
    }
  }

  async getDatabaseUrl() {
    const url = this.get('DATABASE_URL');
    if (!url) {
      throw new Error('DATABASE_URL not configured');
    }
    if (this.isCanaryValue(url)) {
      throw new Error('Using test/canary database URL - not suitable for production');
    }
    return url;
  }

  async getFormattedCredentials() {
    // Return credentials without exposing actual values in logs
    const keys = ['DATABASE_URL', 'AWS_ACCESS_KEY_ID', 'ANTHROPIC_API_KEY', 'STRIPE_SECRET_KEY'];
    const result = {};

    for (const key of keys) {
