      if (value) {
        result[key] = this.isCanaryValue(value) 
          ? '[CANARY/TEST VALUE]' 
          : `[${value.length > 8 ? value.substring(0, 4) + '****' + value.substring(value.length - 4) : '****'}]`;
      } else {
        result[key] = '[NOT SET]';
      }
    }

    return result;
  }
}

module.exports = new SecretsManager();
