// secrets-rotator.js
const jwt = require('jsonwebtoken');

class SecretsManager {
  constructor() {
    this.currentSecret = process.env.JWT_SECRET_KEY;
    this.previousSecret = process.env.PREVIOUS_JWT_SECRET_KEY;
    this.keyRotationInterval = parseInt(process.env.KEY_ROTATION_INTERVAL) || 90 * 24 * 60 * 60; // 90 days
  }

  signToken(payload) {
    return jwt.sign(payload, this.currentSecret, { 
      expiresIn: process.env.JWT_EXPIRES_IN || '24h' 
    });
  }

  verifyToken(token) {
    try {
      // Try current secret first
      return jwt.verify(token, this.currentSecret);
    } catch (err) {
      // If that fails, try previous secret (for rotation period)
      if (this.previousSecret) {
        try {
          return jwt.verify(token, this.previousSecret);
        } catch (verifyErr) {
          throw new Error('Invalid token');
        }
      }
      throw err;
    }
  }
}
